   123  bool KGzipFilter::terminate()
   124  {
   125      if (d->mode == QIODevice::ReadOnly) {
   126          int result = inflateEnd(&d->zStream);
   127          if (result != Z_OK) {
   128              //qCDebug(KArchiveLog) << "inflateEnd returned " << result;
   129              return false;
   130          }
   131      } else if (d->mode == QIODevice::WriteOnly) {
   132          int result = deflateEnd(&d->zStream);
   133          if (result != Z_OK) {
   134              //qCDebug(KArchiveLog) << "deflateEnd returned " << result;
   135              return false;
   136          }
   137      }
   138      d->isInitialized = false;
   139      return true;
   140  }
