   142  void KGzipFilter::reset()
   143  {
   144      if (d->mode == QIODevice::ReadOnly) {
   145          int result = inflateReset(&d->zStream);
   146          if (result != Z_OK) {
   147              //qCDebug(KArchiveLog) << "inflateReset returned " << result;
   148              // TODO return false
   149          }
   150      } else if (d->mode == QIODevice::WriteOnly) {
   151          int result = deflateReset(&d->zStream);
   152          if (result != Z_OK) {
   153              //qCDebug(KArchiveLog) << "deflateReset returned " << result;
   154              // TODO return false
   155          }
   156          d->headerWritten = false;
   157          d->footerWritten = false;
   158      }
   159  }
