   161  bool KGzipFilter::readHeader()
   162  {
   163      // We now rely on zlib to read the full header (see the MAX_WBITS + 32 in init).
   164      // We just use this method to check if the data is actually compressed.
   165
   166  #ifdef DEBUG_GZIP
   167      qCDebug(KArchiveLog) << "avail=" << d->zStream.avail_in;
   168  #endif
   169      // Assume not compressed until we see a gzip header
   170      d->compressed = false;
   171      const Bytef *p = d->zStream.next_in;
   172      int i = d->zStream.avail_in;
   173      if ((i -= 10)  < 0) {
   174          return false;    // Need at least 10 bytes
   175      }
   176  #ifdef DEBUG_GZIP
   177      qCDebug(KArchiveLog) << "first byte is " << QString::number(*p, 16);
   178  #endif
   179      if (*p++ != 0x1f) {
   180          return false;    // GZip magic
   181      }
   182  #ifdef DEBUG_GZIP
   183      qCDebug(KArchiveLog) << "second byte is " << QString::number(*p, 16);
   184  #endif
   185      if (*p++ != 0x8b) {
   186          return false;
   187      }
   188
   189      d->compressed = true;
   190  #ifdef DEBUG_GZIP
   191      qCDebug(KArchiveLog) << "header OK";
   192  #endif
   193      return true;
   194  }
   195
   196  /* Output a 16 bit value, lsb first */
   197  #define put_short(w) \
   198      *p++ = uchar((w) & 0xff); \
   199      *p++ = uchar(ushort(w) >> 8);
   200
   201  /* Output a 32 bit value to the bit stream, lsb first */
   202  #define put_long(n) \
   203      put_short((n) & 0xffff); \
   204      put_short((ulong(n)) >> 16);
   205
   206  bool KGzipFilter::writeHeader(const QByteArray &fileName)
   207  {
   208      Bytef *p = d->zStream.next_out;
   209      int i = d->zStream.avail_out;
   210      *p++ = 0x1f;
   211      *p++ = 0x8b;
   212      *p++ = Z_DEFLATED;
   213      *p++ = ORIG_NAME;
   214      put_long(time(nullptr));     // Modification time (in unix format)
   215      *p++ = 0; // Extra flags (2=max compress, 4=fastest compress)
   216      *p++ = 3; // Unix
   217
   218      uint len = fileName.length();
   219      for (uint j = 0; j < len; ++j) {
   220          *p++ = fileName[j];
   221      }
   222      *p++ = 0;
   223      int headerSize = p - d->zStream.next_out;
   224      i -= headerSize;
   225      Q_ASSERT(i > 0);
   226      d->crc = crc32(0L, nullptr, 0);
   227      d->zStream.next_out = p;
   228      d->zStream.avail_out = i;
   229      d->headerWritten = true;
   230      return true;
   231  }
   232
   233  void KGzipFilter::writeFooter()
   234  {
   235      Q_ASSERT(d->headerWritten);
   236      Q_ASSERT(!d->footerWritten);
   237      Bytef *p = d->zStream.next_out;
   238      int i = d->zStream.avail_out;
   239      //qCDebug(KArchiveLog) << "avail_out=" << i << "writing CRC=" << QString::number(d->crc, 16) << "at p=" << p;
   240      put_long(d->crc);
   241      //qCDebug(KArchiveLog) << "writing totalin=" << d->zStream.total_in << "at p=" << p;
   242      put_long(d->zStream.total_in);
   243      i -= p - d->zStream.next_out;
   244      d->zStream.next_out = p;
   245      d->zStream.avail_out = i;
   246      d->footerWritten = true;
   247  }
