   271  KGzipFilter::Result KGzipFilter::uncompress_noop()
   272  {
   273      // I'm not sure we really need support for that (uncompressed streams),
   274      // but why not, it can't hurt to have it. One case I can think of is someone
   275      // naming a tar file "blah.tar.gz" :-)
   276      if (d->zStream.avail_in > 0) {
   277          int n = (d->zStream.avail_in < d->zStream.avail_out) ? d->zStream.avail_in : d->zStream.avail_out;
   278          memcpy(d->zStream.next_out, d->zStream.next_in, n);
   279          d->zStream.avail_out -= n;
   280          d->zStream.next_in += n;
   281          d->zStream.avail_in -= n;
   282          return KFilterBase::Ok;
   283      } else {
   284          return KFilterBase::End;
   285      }
   286  }
   287
   288  KGzipFilter::Result KGzipFilter::uncompress()
   289  {
   290  #ifndef NDEBUG
   291      if (d->mode == 0) {
   292          //qCWarning(KArchiveLog) << "mode==0; KGzipFilter::init was not called!";
   293          return KFilterBase::Error;
   294      } else if (d->mode == QIODevice::WriteOnly) {
   295          //qCWarning(KArchiveLog) << "uncompress called but the filter was opened for writing!";
   296          return KFilterBase::Error;
   297      }
   298      Q_ASSERT(d->mode == QIODevice::ReadOnly);
   299  #endif
   300
   301      if (!d->compressed) {
   302          return uncompress_noop();
   303      }
   304
   305  #ifdef DEBUG_GZIP
   306      qCDebug(KArchiveLog) << "Calling inflate with avail_in=" << inBufferAvailable() << " avail_out=" << outBufferAvailable();
   307      qCDebug(KArchiveLog) << "    next_in=" << d->zStream.next_in;
   308  #endif
   309
   310      while (d->zStream.avail_in > 0) {
   311          int result = inflate(&d->zStream, Z_SYNC_FLUSH);
   312
   313  #ifdef DEBUG_GZIP
   314          qCDebug(KArchiveLog) << " -> inflate returned " << result;
   315          qCDebug(KArchiveLog) << " now avail_in=" << inBufferAvailable() << " avail_out=" << outBufferAvailable();
   316          qCDebug(KArchiveLog) << "     next_in=" << d->zStream.next_in;
   317  #endif
   318
   319          if (result == Z_OK) {
   320              return KFilterBase::Ok;
   321          }
   322
   323          // We can't handle any other results
   324          if (result != Z_STREAM_END) {
   325              return KFilterBase::Error;
   326          }
   327
   328          // It really was the end
   329          if (d->zStream.avail_in == 0) {
   330              return KFilterBase::End;
   331          }
   332
   333          // Store before resetting
   334          Bytef *data = d->zStream.next_in; // This is increased appropriately by zlib beforehand
   335          uInt size = d->zStream.avail_in;
   336
   337          // Reset the stream, if that fails we assume we're at the end
   338          if (!init(d->mode)) {
   339              return KFilterBase::End;
   340          }
   341
