    89  // Only called when a filename was given
    90  bool KTar::createDevice(QIODevice::OpenMode mode)
    91  {
    92      if (d->mimetype.isEmpty()) {
    93          // Find out mimetype manually
    94
    95          QMimeDatabase db;
    96          QMimeType mime;
    97          if (mode != QIODevice::WriteOnly && QFile::exists(fileName())) {
    98              // Give priority to file contents: if someone renames a .tar.bz2 to .tar.gz,
    99              // we can still do the right thing here.
   100              QFile f(fileName());
   101              if (f.open(QIODevice::ReadOnly)) {
   102                  mime = db.mimeTypeForData(&f);
   103              }
   104              if (!mime.isValid()) {
   105                  // Unable to determine mimetype from contents, get it from file name
   106                  mime = db.mimeTypeForFile(fileName(), QMimeDatabase::MatchExtension);
   107              }
   108          } else {
   109              mime = db.mimeTypeForFile(fileName(), QMimeDatabase::MatchExtension);
   110          }
   111
   112          //qCDebug(KArchiveLog) << mode << mime->name();
   113
   114          if (mime.inherits(QStringLiteral("application/x-compressed-tar")) || mime.inherits(QString::fromLatin1(application_gzip))) {
   115              // gzipped tar file (with possibly invalid file name), ask for gzip filter
   116              d->mimetype = QString::fromLatin1(application_gzip);
   117          } else if (mime.inherits(QStringLiteral("application/x-bzip-compressed-tar")) || mime.inherits(QString::fromLatin1(application_bzip))) {
   118              // bzipped2 tar file (with possibly invalid file name), ask for bz2 filter
   119              d->mimetype = QString::fromLatin1(application_bzip);
   120          } else if (mime.inherits(QStringLiteral("application/x-lzma-compressed-tar")) || mime.inherits(QString::fromLatin1(application_lzma))) {
   121              // lzma compressed tar file (with possibly invalid file name), ask for xz filter
   122              d->mimetype = QString::fromLatin1(application_lzma);
   123          } else if (mime.inherits(QStringLiteral("application/x-xz-compressed-tar")) || mime.inherits(QString::fromLatin1(application_xz))) {
   124              // xz compressed tar file (with possibly invalid name), ask for xz filter
   125              d->mimetype = QString::fromLatin1(application_xz);
   126          }
   127      }
   128
   129      if (d->mimetype == QLatin1String("application/x-tar")) {
   130          return KArchive::createDevice(mode);
   131      } else if (mode == QIODevice::WriteOnly) {
   132          if (!KArchive::createDevice(mode)) {
   133              return false;
   134          }
   135          if (!d->mimetype.isEmpty()) {
   136              // Create a compression filter on top of the QSaveFile device that KArchive created.
   137              //qCDebug(KArchiveLog) << "creating KFilterDev for" << d->mimetype;
   138              KCompressionDevice::CompressionType type = KFilterDev::compressionTypeForMimeType(d->mimetype);
   139              d->compressionDevice = new KCompressionDevice(device(), false, type);
   140              setDevice(d->compressionDevice);
   141          }
   142          return true;
   143      } else {
   144          // The compression filters are very slow with random access.
   145          // So instead of applying the filter to the device,
   146          // the file is completely extracted instead,
   147          // and we work on the extracted tar file.
   148          // This improves the extraction speed by the tar ioslave dramatically,
   149          // if the archive file contains many files.
   150          // This is because the tar ioslave extracts one file after the other and normally
   151          // has to walk through the decompression filter each time.
   152          // Which is in fact nearly as slow as a complete decompression for each file.
   153
   154          Q_ASSERT(!d->tmpFile);
   155          d->tmpFile = new QTemporaryFile();
   156          d->tmpFile->setFileTemplate(QDir::tempPath() + QStringLiteral("/") + QLatin1String("ktar-XXXXXX.tar"));
   157          d->tmpFile->open();
   158          //qCDebug(KArchiveLog) << "creating tempfile:" << d->tmpFile->fileName();
   159
   160          setDevice(d->tmpFile);
   161          return true;
   162      }
   163  }
