   271  qint64 KTar::KTarPrivate::readHeader(char *buffer, QString &name, QString &symlink)
   272  {
   273      name.truncate(0);
   274      symlink.truncate(0);
   275      while (true) {
   276          qint64 n = readRawHeader(buffer);
   277          if (n != 0x200) {
   278              return n;
   279          }
   280
   281          // is it a longlink?
   282          if (strcmp(buffer, "././@LongLink") == 0) {
   283              char typeflag = buffer[0x9c];
   284              QByteArray longlink;
   285              if (readLonglink(buffer, longlink)) {
   286                  switch (typeflag) {
   287                  case 'L':
   288                      name = QFile::decodeName(longlink.constData());
   289                      break;
   290                  case 'K':
   291                      symlink = QFile::decodeName(longlink.constData());
   292                      break;
   293                  }/*end switch*/
   294              }
   295          } else {
   296              break;
   297          }/*end if*/
   298      }/*wend*/
   299
   300      // if not result of longlink, read names directly from the header
   301      if (name.isEmpty())
   302          // there are names that are exactly 100 bytes long
   303          // and neither longlink nor \0 terminated (bug:101472)
   304      {
   305          name = QFile::decodeName(QByteArray(buffer, qstrnlen(buffer, 100)));
   306      }
   307      if (symlink.isEmpty()) {
   308          char *symlinkBuffer = buffer + 0x9d /*?*/;
   309          symlink = QFile::decodeName(QByteArray(symlinkBuffer, qstrnlen(symlinkBuffer, 100)));
   310      }
   311
   312      return 0x200;
   313  }
