   315  /*
   316   * If we have created a temporary file, we have
   317   * to decompress the original file now and write
   318   * the contents to the temporary file.
   319   */
   320  bool KTar::KTarPrivate::fillTempFile(const QString &fileName)
   321  {
   322      if (! tmpFile) {
   323          return true;
   324      }
   325
   326      //qCDebug(KArchiveLog) << "filling tmpFile of mimetype" << mimetype;
   327
   328      KCompressionDevice::CompressionType compressionType = KFilterDev::compressionTypeForMimeType(mimetype);
   329      KCompressionDevice filterDev(fileName, compressionType);
   330
   331      QFile *file = tmpFile;
   332      Q_ASSERT(file->isOpen());
   333      Q_ASSERT(file->openMode() & QIODevice::WriteOnly);
   334      file->seek(0);
   335      QByteArray buffer;
   336      buffer.resize(8 * 1024);
   337      if (! filterDev.open(QIODevice::ReadOnly)) {
   338          q->setErrorString(
   339              tr("File %1 does not exist")
   340              .arg(fileName));
   341          return false;
   342      }
   343      qint64 len = -1;
   344      while (!filterDev.atEnd() && len != 0) {
   345          len = filterDev.read(buffer.data(), buffer.size());
   346          if (len < 0) {   // corrupted archive
   347              q->setErrorString(tr("Archive %1 is corrupt").arg(fileName));
   348              return false;
   349          }
   350          if (file->write(buffer.data(), len) != len) {   // disk full
   351              q->setErrorString(tr("Disk full"));
   352              return false;
   353          }
   354      }
   355      filterDev.close();
   356
   357      file->flush();
   358      file->seek(0);
   359      Q_ASSERT(file->isOpen());
   360      Q_ASSERT(file->openMode() & QIODevice::ReadOnly);

