   206  bool KCompressionDevice::seek(qint64 pos)
   207  {
   208      if (d->deviceReadPos == pos) {
   209          return QIODevice::seek(pos);
   210      }
   211
   212      //qCDebug(KArchiveLog) << "seek(" << pos << ") called, current pos=" << QIODevice::pos();
   213
   214      Q_ASSERT(d->filter->mode() == QIODevice::ReadOnly);
   215
   216      if (pos == 0) {
   217          if (!QIODevice::seek(pos))
   218              return false;
   219
   220          // We can forget about the cached data
   221          d->bNeedHeader = !d->bSkipHeaders;
   222          d->result = KFilterBase::Ok;
   223          d->filter->setInBuffer(nullptr, 0);
   224          d->filter->reset();
   225          d->deviceReadPos = 0;
   226          return d->filter->device()->reset();
   227      }
   228
   229      qint64 bytesToRead;
   230      if (d->deviceReadPos < pos) { // we can start from here
   231          bytesToRead = pos - d->deviceReadPos;
   232          // Since we're going to do a read() below
   233          // we need to reset the internal QIODevice pos to the real position we are
   234          // so that after read() we are indeed pointing to the pos seek
   235          // asked us to be in
   236          if (!QIODevice::seek(d->deviceReadPos)) {
   237              return false;
   238          }
   239      } else {
   240          // we have to start from 0 ! Ugly and slow, but better than the previous
   241          // solution (KTarGz was allocating everything into memory)
   242          if (!seek(0)) { // recursive
   243              return false;
   244          }
   245          bytesToRead = pos;
   246      }
   247
   248      //qCDebug(KArchiveLog) << "reading " << bytesToRead << " dummy bytes";
   249      QByteArray dummy(qMin(bytesToRead, qint64(3 * BUFFER_SIZE)), 0);
   250      const bool result = (read(dummy.data(), bytesToRead) == bytesToRead);
   251      return result;
   252  }
