   254  bool KCompressionDevice::atEnd() const
   255  {
   256      return (d->type == KCompressionDevice::None || d->result == KFilterBase::End)
   257             && QIODevice::atEnd() // take QIODevice's internal buffer into account
   258             && d->filter->device()->atEnd();
   259  }
