   267  bool KArchive::addLocalFile(const QString &fileName, const QString &destName)
   268  {
   269      QFileInfo fileInfo(fileName);
   270      if (!fileInfo.isFile() && !fileInfo.isSymLink()) {
   271          setErrorString(
   272              tr("%1 doesn't exist or is not a regular file.")
   273              .arg(fileName));
   274          return false;
   275      }
   276
   277  #if defined(Q_OS_UNIX)
   278  #define STAT_METHOD QT_LSTAT
   279  #else
   280  #define STAT_METHOD QT_STAT
   281  #endif
   282      QT_STATBUF fi;
   283      if (STAT_METHOD(QFile::encodeName(fileName).constData(), &fi) == -1) {
   284          setErrorString(
   285              tr("Failed accessing the file %1 for adding to the archive. The error was: %2")
   286              .arg(fileName)
   287              .arg(QLatin1Literal{strerror(errno)}));
   288          return false;
   289      }
   290
   291      if (fileInfo.isSymLink()) {
   292          QString symLinkTarget;
   293          // Do NOT use fileInfo.readLink() for unix symlinks!
   294          // It returns the -full- path to the target, while we want the target string "as is".
   295  #if defined(Q_OS_UNIX) && !defined(Q_OS_OS2EMX)
   296          const QByteArray encodedFileName = QFile::encodeName(fileName);
   297          QByteArray s;
   298  #if defined(PATH_MAX)
   299          s.resize(PATH_MAX + 1);
   300  #else
   301          int path_max = pathconf(encodedFileName.data(), _PC_PATH_MAX);
   302          if (path_max <= 0) {
   303              path_max = 4096;
   304          }
   305          s.resize(path_max);
   306  #endif
   307          int len = readlink(encodedFileName.data(), s.data(), s.size() - 1);
   308          if (len >= 0) {
   309              s[len] = '\0';
   310              symLinkTarget = QFile::decodeName(s.constData());
   311          }
   312  #endif
   313          if (symLinkTarget.isEmpty()) { // Mac or Windows
   314              symLinkTarget = fileInfo.symLinkTarget();
   315          }
   316          return writeSymLink(destName, symLinkTarget, fileInfo.owner(),
   317                              fileInfo.group(), fi.st_mode, fileInfo.lastRead(), fileInfo.lastModified(),
   318                              fileInfo.created());
   319      }/*end if*/
   320
   321      qint64 size = fileInfo.size();
   322
   323      // the file must be opened before prepareWriting is called, otherwise
   324      // if the opening fails, no content will follow the already written
   325      // header and the tar file is effectively f*cked up
   326      QFile file(fileName);
   327      if (!file.open(QIODevice::ReadOnly)) {
   328          setErrorString(
   329              tr("Couldn't open file %1: %2")
   330              .arg(fileName, file.errorString()));
   331          return false;
   332      }
   333
   334      if (!prepareWriting(destName, fileInfo.owner(), fileInfo.group(), size,
   335                          fi.st_mode, fileInfo.lastRead(), fileInfo.lastModified(), fileInfo.created())) {
   336          //qCWarning(KArchiveLog) << " prepareWriting" << destName << "failed";
   337          return false;
   338      }
   339
   340      // Read and write data in chunks to minimize memory usage
   341      QByteArray array;
   342      array.resize(int(qMin(qint64(1024 * 1024), size)));
   343      qint64 n;
   344      qint64 total = 0;
   345      while ((n = file.read(array.data(), array.size())) > 0) {
   346          if (!writeData(array.data(), n)) {
   347              //qCWarning(KArchiveLog) << "writeData failed";
   348              return false;
   349          }
   350          total += n;
   351      }
   352      Q_ASSERT(total == size);
   353
   354      if (!finishWriting(size)) {
   355          //qCWarning(KArchiveLog) << "finishWriting failed";
   356          return false;
   357      }
   358      return true;
   359  }
