   487                  // for isDumpDir we will skip the additional info about that dirs contents
   488                  if (isDumpDir) {
   489                      //qCDebug(KArchiveLog) << nm << "isDumpDir";
   490                      e = new KArchiveDirectory(this, nm, access, KArchivePrivate::time_tToDateTime(time), user, group, symlink);
   491                  } else {
   492
   493                      // Let's hack around hard links. Our classes don't support that, so make them symlinks
   494                      if (typeflag == '1') {
