   746  bool KTar::doPrepareWriting(const QString &name, const QString &user,
   747                              const QString &group, qint64 size, mode_t perm,
   748                              const QDateTime & /*atime*/, const QDateTime &mtime, const QDateTime & /*ctime*/)
   749  {
   750      if (!isOpen()) {
   751          setErrorString(tr("Application error: TAR file must be open before being written into"));
   752          qCWarning(KArchiveLog) << "doPrepareWriting failed: !isOpen()";
   753          return false;
   754      }
   755
   756      if (!(mode() & QIODevice::WriteOnly)) {
   757          setErrorString(tr("Application error: attempted to write into non-writable 7-Zip file"));
   758          qCWarning(KArchiveLog) << "doPrepareWriting failed: !(mode() & QIODevice::WriteOnly)";
   759          return false;
   760      }
   761
   762      // In some tar files we can find dir/./file => call cleanPath
   763      QString fileName(QDir::cleanPath(name));
   764
   765      /*
   766        // Create toplevel dirs
   767        // Commented out by David since it's not necessary, and if anybody thinks it is,
   768        // he needs to implement a findOrCreate equivalent in writeDir.
   769        // But as KTar and the "tar" program both handle tar files without
   770        // dir entries, there's really no need for that
   771        QString tmp ( fileName );
   772        int i = tmp.lastIndexOf( '/' );
   773        if ( i != -1 )
   774        {
   775        QString d = tmp.left( i + 1 ); // contains trailing slash
   776        if ( !m_dirList.contains( d ) )
   777        {
   778        tmp = tmp.mid( i + 1 );
   779        writeDir( d, user, group ); // WARNING : this one doesn't create its toplevel dirs
   780        }
   781        }
   782      */
   783
   784      char buffer[0x201];
   785      memset(buffer, 0, 0x200);
   786      if ((mode() & QIODevice::ReadWrite) == QIODevice::ReadWrite) {
   787          device()->seek(d->tarEnd);    // Go to end of archive as might have moved with a read
   788      }
   789
   790      // provide converted stuff we need later on
   791      const QByteArray encodedFileName = QFile::encodeName(fileName);
   792      const QByteArray uname = user.toLocal8Bit();
   793      const QByteArray gname = group.toLocal8Bit();
   794
   795      // If more than 100 bytes, we need to use the LongLink trick
   796      if (encodedFileName.length() > 99) {
   797          d->writeLonglink(buffer, encodedFileName, 'L', uname.constData(), gname.constData());
   798      }
   799
   800      // Write (potentially truncated) name
   801      strncpy(buffer, encodedFileName.constData(), 99);
   802      buffer[99] = 0;
   803      // zero out the rest (except for what gets filled anyways)
   804      memset(buffer + 0x9d, 0, 0x200 - 0x9d);
   805
   806      QByteArray permstr = QByteArray::number(static_cast<unsigned int>(perm), 8);
   807      permstr = permstr.rightJustified(6, '0');
   808      d->fillBuffer(buffer, permstr.constData(), size, mtime, 0x30, uname.constData(), gname.constData());
   809
